import { readFile, mkdir, writeFile } from "node:fs/promises";
const root = new URL("../", import.meta.url);
const [font, logo] = await Promise.all([
  readFile(new URL("src/assets/fonts/inter/InterDisplay-Bold-latin.ttf", root)),
  readFile(new URL("src/assets/brand/pocket-creatives-logo-og.png", root)),
]);
const directory = new URL("src/generated/", root);
await mkdir(directory, { recursive: true });
await writeFile(
  new URL("social-card-assets.ts", directory),
  "// Generated by scripts/setup-social-card.mjs; original licensed assets remain in src/assets.\n" +
    `export const socialCardFont = ${JSON.stringify(font.toString("base64"))};\n` +
    `export const socialCardLogo = ${JSON.stringify("data:image/png;base64," + logo.toString("base64"))};\n`,
);
console.log("Prepared bundled social card assets for Node and Workers.");
